code.cpp:
class Solution {
public:
    int findKthNumber(int m, int n, int k) {
        if (m > n) swap(m, n);
        long long lo = 1, hi = (long long)m * n;
        while (lo < hi) {
            long long mid = lo + (hi - lo) / 2;
            long long cnt = 0;
            for (int i = 1; i <= m; i++) {
                cnt += min((long long)n, mid / i);
            }
            if (cnt >= k) hi = mid;
            else lo = mid + 1;
        }
        return (int)lo;
    }
};
